import Foundation

// Everything a person reads in the app says Rany and never points to the website.
// Historical release notes and generated data files stay byte-for-byte as shipped;
// they pass through here only when displayed.
enum RanyCopy {
    static func visible(_ text: String) -> String {
        if let rewritten = notes[text] { return rewritten }
        return text.replacingOccurrences(of:"Wany",with:"Rany").replacingOccurrences(of:"WANY",with:"RANY")
    }
